/**
 * Orientation landmarks. Coordinates: IAU / USGS Gazetteer of Planetary Nomenclature,
 * MOON_nomenclature_center_pts (GCS_Moon_2000, R = 1737.4 km; 0–360°E converted to
 * −180…180°E), rounded to 0.01°. Downloaded 2026-11-14.
 *
 * LANDMARK_VALIDATION was generated by sampling the GLB's OWN embedded texture through
 * the verified `latLonToModel` transform (ray–triangle hit → UV → 13×13 px mean
 * luminance; texture median 110) — docs/PHASE6A_INTERACTIVE_MOON_REPORT.md §3.
 * Rule: a mare must be below the median AND ≥ 25 % darker than the point mirrored in
 * `mirror` (longitude → detects an east/west flip, latitude → a north/south flip);
 * a bright crater the reverse. All seven pass; an east/west-mirrored model would fail at
 * least the five longitude-mirror checks.
 *
 * Polar landmarks (`expect: null`) are shown for navigation only. Shoemaker’s 52 km
 * double ring was checked visually in a polar-stereographic render of the texture.
 */
export interface Landmark {
  id: string
  name: string
  lat: number
  lon: number
  expect: 'dark' | 'bright' | null
  mirror?: 'lon' | 'lat'
}

